package org.apache.commons.cli.help;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

import java.lang.reflect.Field;

import org.junit.Test;

public class PadTests {

    private TextStyle styleWith(TextStyle.Alignment alignment, int maxWidth, int indent) throws Exception {
        TextStyle style = TextStyle.builder().get();
        setField(style, "alignment", alignment);
        setField(style, "maxWidth", maxWidth);
        setField(style, "indent", indent);
        return style;
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field f = TextStyle.class.getDeclaredField(fieldName);
        f.setAccessible(true);
        f.set(target, value);
    }

    @Test
    public void testCenterPadsToMaxWidth() throws Exception {
        TextStyle s = styleWith(TextStyle.Alignment.CENTER, 6, 3);
        CharSequence out = s.pad(false, "Hi");
        assertEquals("  Hi  ", out.toString());
        assertEquals(6, out.length());
    }

    @Test
    public void testLeftPadsToMaxWidthWithIndent() throws Exception {
        TextStyle s = styleWith(TextStyle.Alignment.LEFT, 6, 2);
        CharSequence out = s.pad(true, "Hi");
        // Expect indentation (2), text (2), and remaining spaces to reach maxWidth (2)
        assertEquals("  Hi  ", out.toString());
        assertEquals(6, out.length());
    }

    @Test
    public void testRightPadsToMaxWidthWithIndent() throws Exception {
        TextStyle s = styleWith(TextStyle.Alignment.RIGHT, 6, 2);
        CharSequence out = s.pad(true, "Hi");
        // Expect indent (2) + padding (2) + text (2) to total maxWidth 6
        assertEquals("    Hi", out.toString());
        assertEquals(6, out.length());
    }

    @Test
    public void testReturnsOriginalWhenTextLongerThanMaxWidth() throws Exception {
        TextStyle s = styleWith(TextStyle.Alignment.LEFT, 4, 2);
        StringBuilder sb = new StringBuilder("Hello");
        CharSequence out = s.pad(true, sb);
        // When text length >= maxWidth the original CharSequence instance should be returned
        assertSame(sb, out);
    }

    @Test
    public void testCenterWithUnsetMaxWidthAndIndent() throws Exception {
        TextStyle s = styleWith(TextStyle.Alignment.CENTER, TextStyle.UNSET_MAX_WIDTH, 3);
        CharSequence out = s.pad(true, "Hi");
        // For unset maxWidth and addIndent true, padLen == indent (3) => left = 1, rest = 2
        assertEquals(" Hi  ", out.toString());
    }

    @Test
    public void testLeftAndRightWithUnsetMaxWidthAddIndent() throws Exception {
        TextStyle leftStyle = styleWith(TextStyle.Alignment.LEFT, TextStyle.UNSET_MAX_WIDTH, 2);
        TextStyle rightStyle = styleWith(TextStyle.Alignment.RIGHT, TextStyle.UNSET_MAX_WIDTH, 2);

        CharSequence outLeft = leftStyle.pad(true, "Hi");
        CharSequence outRight = rightStyle.pad(true, "Hi");

        // For unset maxWidth and addIndent true, both LEFT and RIGHT should simply prefix the indent and not append trailing padding
        assertEquals("  Hi", outLeft.toString());
        assertEquals("  Hi", outRight.toString());
    }
}

